128:   cargarRoles (){
129:     // obtener lista de roles
130:     const user = (localStorage.getItem('user'));
131:     let roleUser = [];
132:     if (user) {
133:       roleUser = JSON.parse(atob(user)).userService.role;
134:     } else {
135:       console.error("Sin roles almacenados en localStorage para mostrar");
136:     }
137:     let roles = roleUser.filter ( (role: string | string[]) => !role.includes('/') );
138:     if (roles.length !== 0) {
139:       this.roles_sga = roles;
140:     } else {
141:       roles.push('ASPIRANTE');
