13:  */
14: @Injectable({
15:     providedIn: 'root',
16: })
17: export class RequestManager {
18:     private path!: string;
19:     public httpOptions: any;
20:     constructor(
21:         private http: HttpClient,
22:         private errManager: HttpErrorManager
23:     ) {
24:         const acces_token = window.localStorage.getItem('access_token');
25:         if (acces_token !== null) {
26:             this.httpOptions = {
27:                  headers: new HttpHeaders({
28:                    'Content-Type': 'application/json',
29:                    'Authorization': `Bearer ${acces_token}`,
30:                  }),
31:             }
32:         }
33:     }
34: 
35: 
36:     /**
37:      * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
38:      * @param service: string
39:      */
40:     public setPath(service: string) {
41:         this.path = (environment as any)[service];
42:       }
43: 
44:     /**
45:      * Perform a GET http request
46:      * @param endpoint service's end-point
47:      * @param params (an Key, Value object with que query params for the request)
48:      * @returns Observable<any>
49:      */
50:     get(endpoint: any) {
51: 
52:         return this.http.get<any>(`${this.path}${endpoint}`, this.httpOptions).pipe(
53:             map(
54:                 (res) => {
55:                     const responseBody = res as { Body?: any };
56:                     return responseBody?.Body ?? res;
57:                 },
58:             ),
59:             catchError(this.errManager.handleError.bind(this)),
60:         );
61:         
62:     }
63: 
64:     /**
65:      * Perform a POST http request
66:      * @param endpoint service's end-point
67:      * @param element data to send as JSON
68:      * @returns Observable<any>
69:      */
70:     post(endpoint: any, element: any) {
71:         return this.http.post<any>(`${this.path}${endpoint}`, element, this.httpOptions).pipe(
72:             catchError(this.errManager.handleError),
73:         );
74:     }
75: 
76:     /**
77:      * Perform a POST http request
78:      * @param endpoint service's end-point
79:      * @param element data to send as JSON
80:      * @returns Observable<any>
81:      */
82:     post_file(endpoint: any, element: any) {
83:         return this.http.post<any>(`${this.path}${endpoint}`, element, {
84:             headers: new HttpHeaders({
85:                 'Content-Type': 'multipart/form-data',
86:             })
87:         }).pipe(
88:             catchError(this.errManager.handleError),
89:         );
90:     }
91: 
92:     /**
93:      * Perform a PUT http request
94:      * @param endpoint service's end-point
95:      * @param element data to send as JSON, With the id to UPDATE
96:      * @returns Observable<any>
97:      */
98:     put(endpoint: any, element: { Id: any; }) {
99:         const path = (element.Id) ? `${this.path}${endpoint}/${element.Id}` : `${this.path}${endpoint}`;
100:         return this.http.put<any>(path, element, this.httpOptions).pipe(
101:             catchError(this.errManager.handleError),
102:         );
103:     }
104: 
105:     /**
106:      * Perform a DELETE http request
107:      * @param endpoint service's end-point
108:      * @param id element's id for remove
109:      * @returns Observable<any>
110:      */
111:     delete(endpoint: any, id: any) {
112:         return this.http.delete<any>(`${this.path}${endpoint}/${id}`, this.httpOptions).pipe(
113:             catchError(this.errManager.handleError),
114:         );
115:     }
116: };

